import { describe, expect, it } from 'vitest';
import type { Feature } from '../../src/types';
import { getQualifier } from '../../src/seq/features';
import { translateFeature } from '../../src/seq/translate';
import { parseGenbank, writeGenbank } from '../../src/io/genbank';
import { deleteRange, insertBases, replaceRange } from '../../src/ops/edit';
import { extractRange } from '../../src/ops/transform';

const pbr = parseGenbank(readFileSync(new URL('../fixtures/genbank/pBR322_J01749.gb', import.meta.url), 'utf8')).records[0];
const tet = pbr.features.find((f) => f.type === 'CDS' && f.name === 'tet') as Feature; // 86..1276
const s = tet.segments[0].start;
const stored = (rec: { features: Feature[] }) => getQualifier((rec.features.find((f) => f.id === tet.id) as Feature).qualifiers, 'translation');
const computed = (rec: Parameters<typeof translateFeature>[0]) => translateFeature(rec, rec.features.find((f) => f.id === tet.id) as Feature).replace(/\*$/, '');

describe('ops-science: /translation of an edited CDS', () => {
  it('fixture: stored /translation equals the computed one', () => {
    expect(stored(pbr)).toBe(computed(pbr)); // passes
  });
  it('point mutation L11W (replaceRange CTG -> TGG) keeps the old /translation', () => {
    const out = replaceRange(pbr, { start: s + 30, end: s + 33 }, 'TGG');
    expect(computed(out).slice(0, 12)).toBe('MKSNNALIVIWG'); // passes
    expect(stored(out)).toBe(computed(out)); // FAILS
  });
  it('in-frame codon deletion (deleteRange) keeps the old /translation', () => {
    const out = deleteRange(pbr, { start: s + 30, end: s + 33 });
    expect(stored(out)).toBe(computed(out)); // FAILS
  });
  it('in-frame insertion (insertBases) keeps the old /translation, and writeGenbank exports it', () => {
    const out = insertBases(pbr, s + 30, 'TGG');
    expect(writeGenbank(out).replace(/\s+/g, '')).toContain('/translation="MKSNNALIVILGTVTLDAVG'); // passes: old protein exported
    expect(stored(out)).toBe(computed(out)); // FAILS
  });
  it("extractRange clipping the 5' end keeps the full-length /translation", () => {
    const piece = extractRange(pbr, { start: s + 300, end: 1300 });
    expect(stored(piece)).toBe(computed(piece)); // FAILS
  });
});
