import type { SeqRecord } from '../../src/types';
import { rotateOrigin, reverseComplementRecord } from '../../src/ops/transform';

const circ = (seq: string, features: SeqRecord['features'] = []): SeqRecord => ({
  id: 'd', name: 'n', description: '', seq, topology: 'circular', molecule: 'DNA', features, primers: [], meta: {},
});

describe('rotate / reverse-complement round trips with position-bearing qualifiers', () => {
  const rec = circ('ATGAAATGAGGGCCCTTTAAACCCGGGTTTAAA', [
    { id: 'cds', type: 'CDS', name: 'cds', strand: 1, segments: [{ start: 0, end: 12 }], qualifiers: [{ key: 'transl_except', value: '(pos:7..9,aa:Sec)' }] },
    { id: 'rep', type: 'repeat_region', name: 'rep', strand: 0, segments: [{ start: 12, end: 30 }], qualifiers: [{ key: 'rpt_unit_range', value: '13..18' }] },
  ]);
  const L = rec.seq.length;
  it('k = 7 then L - 7 keeps /transl_except', () => {
    expect(rotateOrigin(rotateOrigin(rec, 7), L - 7).features[0].qualifiers).toEqual(rec.features[0].qualifiers);
  });
