    expect(rotateOrigin(rotateOrigin(rec, 14), L - 14).features[1].qualifiers).toEqual(rec.features[1].qualifiers);
  });
  it('reverse complement twice keeps a one-base /rpt_unit_range', () => {
    const one = circ(rec.seq, [{ id: 'r', type: 'repeat_region', name: 'r', strand: 0, segments: [{ start: 10, end: 20 }], qualifiers: [{ key: 'rpt_unit_range', value: '12..12' }] }]);
    expect(reverseComplementRecord(reverseComplementRecord(one))).toEqual(one);
  });
});

